UpdateSchema "CIMDATA=<CIMStandardDataConnection xsi:type='typens:CIMStandardDataConnection' xmlns:xsi='http://www.w3.org/2001/XMLSchema-instance' xmlns:xs='http://www.w3.org/2001/XMLSchema' xmlns:typens='http://www.esri.com/schemas/ArcGIS/3.4.0'><WorkspaceConnectionString>DATABASE=C:\Users\dh2306\Documents\ArcGIS\Projects\mslc_assessment\mslc_assessment.gdb</WorkspaceConnectionString><WorkspaceFactory>FileGDB</WorkspaceFactory><Dataset>assesment_points</Dataset><DatasetType>esriDTFeatureClass</DatasetType></CIMStandardDataConnection>" "<operationSequence><workflow><AddAttributeRule><rule_name>New Rule</rule_name><rule_type>CALCULATION</rule_type><expression>var classCode = $feature.ground_truth;

var legendDict = {
    0: "Nodata",
    1: "Open Water",
    2: "Impervious Structures",
    3: "Impervious Surfaces",
    4: "Barren Land",
    5: "Tree Canopy/Woody Vegetation",
    6: "Low Vegetation/Herbaceous",
    7: "Cultivated Crops",
    8: "Unclassified"
};

return IIf(HasKey(legendDict, classCode), legendDict[classCode], "Unknown");
</expression><is_editable>False</is_editable><triggering_events_insert>True</triggering_events_insert><triggering_events_delete>False</triggering_events_delete><triggering_events_update>True</triggering_events_update><field_name>ground_truth_class_name</field_name><exclude_from_client_eval>False</exclude_from_client_eval><batch>False</batch><severity>-1</severity><category>-1</category></AddAttributeRule><ReorderAttributeRule><rule_name>New Rule</rule_name><evaluation_order>1</evaluation_order></ReorderAttributeRule></workflow></operationSequence>"

